            ttb_match.append(1 if resp == 1 else 0)
        # Trials 8 & 16: TTB picks A (cue 0), Tallying picks B (B wins 2 cues to 1)
        elif a == (1, 1, 0, 0) and b == (0, 1, 1, 1):
